<?php $orderLabels = ['pending'=>'در انتظار پرداخت','paid'=>'پرداخت‌شده','failed'=>'ناموفق','canceled'=>'لغوشده','expired'=>'منقضی‌شده','refunded'=>'بازگشت وجه']; $transactionLabels=['initiated'=>'ایجادشده','verified'=>'تأییدشده','failed'=>'ناموفق','canceled'=>'لغوشده','expired'=>'منقضی‌شده']; ?>
<section class="user-area"><div class="container user-layout"><?php require view_path('components/user/sidebar.php'); ?><div class="user-main"><header class="user-page-head"><div><div class="breadcrumb"><a href="/orders">سفارش‌ها</a><span>←</span><span class="ltr"><?= e($order['number']) ?></span></div><h1>جزئیات سفارش</h1><p><?= e($order['item_title']) ?></p></div><span class="order-status order-status--<?= e($order['status']) ?>"><?= e($orderLabels[$order['status']] ?? $order['status']) ?></span></header><div class="order-detail-grid"><section class="user-panel"><header><div><span class="eyebrow">Order</span><h2>اطلاعات سفارش</h2></div></header><dl class="order-detail-list"><div><dt>شماره سفارش</dt><dd class="ltr"><?= e($order['number']) ?></dd></div><div><dt>خریدار</dt><dd><?= e($order['customer_name']) ?></dd></div><div><dt>محصول</dt><dd><?= e($order['item_title']) ?></dd></div><div><dt>مبلغ</dt><dd><?= number_format((int) $order['amount']) ?> تومان</dd></div><div><dt>تاریخ ایجاد</dt><dd class="ltr"><?= e($order['created_at']) ?></dd></div><?php if ($order['paid_at']): ?><div><dt>تاریخ پرداخت</dt><dd class="ltr"><?= e($order['paid_at']) ?></dd></div><?php endif; ?></dl></section><section class="user-panel"><header><div><span class="eyebrow">Transactions</span><h2>تراکنش‌ها</h2></div></header><div class="transaction-list"><?php foreach ($transactions as $transaction): ?><article><div><strong><?= e($transaction['gateway']) ?></strong><small class="ltr"><?= e($transaction['authority']) ?></small></div><span class="order-status order-status--<?= e($transaction['status']) ?>"><?= e($transactionLabels[$transaction['status']] ?? $transaction['status']) ?></span><?php if ($transaction['reference_id']): ?><p>کد پیگیری: <b class="ltr"><?= e($transaction['reference_id']) ?></b></p><?php endif; ?></article><?php endforeach; ?></div></section></div></div></div></section>
